"""Equity research brief rendering, Task 1 bonus.

Markdown is the single source. The HTML page is generated from it rather than written
separately, so the two artefacts cannot drift apart.
"""

import base64
import datetime as dt
from pathlib import Path

import markdown as md_lib
import pandas as pd

from task1_financial.src import charts

DISCLAIMER = (
    "This document is generated by an automated research pipeline for technical "
    "demonstration purposes only. It is not investment advice, not a recommendation to "
    "buy or sell any security, and not a solicitation of any kind. The signal is "
    "produced by a language model reasoning over historical price data and public news "
    "headlines. It has not been reviewed by a licensed analyst. Past performance does "
    "not predict future results, and technical indicators describe what price has "
    "already done rather than what it will do. Anyone acting on this material does so "
    "entirely at their own risk and should consult a qualified financial adviser."
)

SIGNAL_TONE = {"Buy": "buy", "Hold": "hold", "Sell": "sell"}
SENTIMENT_TONE = {"positive": "buy", "negative": "sell", "neutral": "hold"}


def _n(value, dp: int = 2, suffix: str = "", dash: str = "n/a") -> str:
    if value is None or (isinstance(value, float) and pd.isna(value)):
        return dash
    if isinstance(value, (int, float)):
        return f"{value:,.{dp}f}{suffix}"
    return str(value)


def _big(value) -> str:
    if value is None:
        return "n/a"
    for cutoff, unit in ((1e12, "T"), (1e9, "B"), (1e6, "M")):
        if abs(value) >= cutoff:
            return f"{value / cutoff:,.2f}{unit}"
    return f"{value:,.0f}"


def _range_position(summary: dict) -> str:
    price = summary.get("current_price")
    high, low = summary.get("week52_high"), summary.get("week52_low")
    if None in (price, high, low) or high == low:
        return "n/a"
    pct = (price - low) / (high - low) * 100
    return f"{pct:.0f}% of the 52-week range"


def render_markdown(summary: dict, analysis: dict, headlines: list[dict]) -> str:
    ind = summary.get("indicators", {})
    momentum = summary.get("momentum", {})
    agg = analysis.get("aggregate_sentiment")
    signal = analysis.get("signal")
    generated = dt.datetime.now().strftime("%d %B %Y at %H:%M")

    lines = [
        f"# {summary.get('company_name', summary['ticker'])} ({summary['ticker']})",
        "",
        f"Equity research brief, data as of {summary.get('as_of', 'unknown')}. "
        f"Generated {generated}.",
        "",
        "## Company snapshot",
        "",
        "| Metric | Value |",
        "| --- | --- |",
        f"| Current price | {_n(summary.get('current_price'))} {summary.get('currency', '')} |",
        f"| 52-week range | {_n(summary.get('week52_low'))} to {_n(summary.get('week52_high'))} |",
        f"| Position in range | {_range_position(summary)} |",
        f"| P/E ratio | {_n(summary.get('pe_ratio'))} |",
        f"| Market cap | {_big(summary.get('market_cap'))} |",
        f"| Year to date return | {_n(summary.get('ytd_return_pct'), 2, '%')} |",
        f"| Sector | {summary.get('sector') or 'n/a'} |",
        f"| Bars analysed | {summary.get('bars_analysed', 'n/a')} since {summary.get('history_start', 'n/a')} |",
        "",
        "## Technical outlook",
        "",
        "| Indicator | Value |",
        "| --- | --- |",
        f"| SMA 50 | {_n(ind.get('sma_50'))} |",
        f"| SMA 200 | {_n(ind.get('sma_200'))} |",
        f"| RSI 14 | {_n(ind.get('rsi_14'))} |",
        f"| MACD line | {_n(ind.get('macd'), 3)} |",
        f"| MACD signal | {_n(ind.get('macd_signal'), 3)} |",
        f"| MACD histogram | {_n(ind.get('macd_hist'), 3)} |",
        f"| Bollinger upper | {_n(ind.get('bb_upper'))} |",
        f"| Bollinger mid | {_n(ind.get('bb_mid'))} |",
        f"| Bollinger lower | {_n(ind.get('bb_lower'))} |",
        f"| Percent B | {_n(ind.get('bb_pct_b'), 3)} |",
        "",
        f"**Rule-based momentum reading: {momentum.get('signal', 'n/a')}** "
        f"(score {_n(momentum.get('score'), 2)} on a scale of -1 to 1).",
        "",
    ]

    components = momentum.get("components") or {}
    if components:
        readable = ", ".join(
            f"{k.replace('_', ' ')} {'+1' if v > 0 else ('0' if v == 0 else '-1')}"
            for k, v in components.items()
        )
        lines += [f"Components: {readable}.", ""]
    if momentum.get("flags"):
        lines += [f"Flags: {', '.join(momentum['flags'])}.", ""]

    lines += ["## News sentiment", ""]
    if agg:
        lines += [
            f"Aggregate sentiment is **{agg['label']}** at a confidence-weighted score of "
            f"{_n(agg['score'], 3)} on a scale of -1 to 1, across "
            f"{agg['positive'] + agg['negative'] + agg['neutral']} classified headlines "
            f"({agg['positive']} positive, {agg['negative']} negative, {agg['neutral']} neutral) "
            f"with a mean confidence of {_n(agg['mean_confidence'], 2)}.",
            "",
        ]
        rate = analysis.get("classification_success_rate")
        if rate is not None and rate < 1.0:
            lines += [
                f"Note: {len(analysis.get('sentiment_failures', []))} headline(s) failed "
                f"validation and were excluded, a classification success rate of "
                f"{rate * 100:.0f}%.",
                "",
            ]
    else:
        lines += ["No headline sentiment could be retrieved for this run.", ""]

    ranked = sorted(
        analysis.get("headline_sentiment", []),
        key=lambda r: (r["sentiment"] != "neutral", r["confidence"]),
        reverse=True,
    )[:3]
    if ranked:
        lines += ["### Top three headlines", ""]
        for i, r in enumerate(ranked, 1):
            lines += [
                f"{i}. **{r['headline']}**  ",
                f"   *{r['sentiment']}, confidence {r['confidence']:.2f}*. {r['brief_reason']}",
                "",
            ]

    lines += ["## Recommendation", ""]
    if signal:
        lines += [f"### {signal['signal']}", "", signal["justification"], ""]
        if signal.get("key_drivers"):
            lines += ["**Key drivers**", ""]
            lines += [f"- {d}" for d in signal["key_drivers"]]
            lines += [""]
    else:
        lines += [
            "No recommendation was produced for this run.",
            "",
            f"Reason: {analysis.get('signal_error', 'unknown')}.",
            "",
        ]

    lines += ["## Risk disclaimer", "", DISCLAIMER, ""]
    return "\n".join(lines)


