def render_html(markdown_text: str, chart_png: bytes | None, summary: dict, analysis: dict) -> str:
    body = md_lib.markdown(markdown_text, extensions=["tables", "sane_lists"])

    if chart_png:
        encoded = base64.b64encode(chart_png).decode("ascii")
        figure = (
            f'<div class="chart"><img alt="Price with SMA50, SMA200, Bollinger bands, '
            f'RSI and MACD for {summary["ticker"]}" '
            f'src="data:image/png;base64,{encoded}"></div>'
        )
        # Drop the chart in ahead of the technical section it explains.
        marker = "<h2>Technical outlook</h2>"
        body = body.replace(marker, figure + marker, 1) if marker in body else figure + body

    signal = analysis.get("signal")
    if signal:
        tone = SIGNAL_TONE.get(signal["signal"], "hold")
        body = body.replace(
            f"<h3>{signal['signal']}</h3>",
            f'<p><span class="verdict {tone}">{signal["signal"]}</span></p>',
            1,
        )

    body = body.replace("<h2>Risk disclaimer</h2>", '<h2>Risk disclaimer</h2><div class="disclaimer">')
    body = body.rstrip() + "</div>"

    generated = dt.datetime.now().strftime("%d %B %Y %H:%M")
    return f"""<!DOCTYPE html>
<html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>{summary.get('company_name', summary['ticker'])} equity research brief</title>
<style>{CSS}</style></head>
<body><div class="page">{body}
<div class="footer"><span>CDAZZDEV Senior MLE assessment, Task 1</span>
<span>Generated {generated}</span></div>
</div></body></html>"""


def write_report(
    summary: dict, analysis: dict, headlines: list[dict],
    enriched: pd.DataFrame | None = None, output_dir: Path | None = None,
) -> dict[str, Path]:
    output_dir = Path(output_dir or Path(__file__).resolve().parents[1] / "outputs")
    output_dir.mkdir(parents=True, exist_ok=True)
    ticker = summary["ticker"]

    chart_png = None
    if enriched is not None and not enriched.empty:
        chart_png = charts.build_chart(
            enriched, ticker, summary.get("company_name", ticker)
        )

    markdown_text = render_markdown(summary, analysis, headlines)
    html = render_html(markdown_text, chart_png, summary, analysis)

    written = {}
    md_path = output_dir / f"{ticker}_brief.md"
    md_path.write_text(markdown_text, encoding="utf-8")
    written["markdown"] = md_path

    html_path = output_dir / f"{ticker}_brief.html"
    html_path.write_text(html, encoding="utf-8")
    written["html"] = html_path

    if chart_png:
        png_path = output_dir / f"{ticker}_chart.png"
        png_path.write_bytes(chart_png)
        written["chart"] = png_path

    return written
